CREATE POLICY "anyone reads cake photos" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'cake-photos');
CREATE POLICY "admins upload cake photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'cake-photos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "admins update cake photos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'cake-photos' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY "admins delete cake photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'cake-photos' AND public.has_role(auth.uid(), 'admin'));